    def get_transcript(
        self,
        *,
        url: str,
        language: str | None = None,
        use_ai_as_fallback: bool | None = None,
        timeout: float | Timeout | NotGiven | None = not_given,
    ) -> TikTokTranscriptResponse:
        """Returns a video's captions as one WEBVTT string, with its `id` and `url`. Without `language` the captions are in the video's original language. Costs 1 credit.

        Args:
            url: A TikTok video or photo post URL:
                `https://www.tiktok.com/@<handle>/video/<id>`, `/photo/<id>`, or a
                `https://vm.tiktok.com/<code>/` share link.
            language: Two-letter language code of the captions, such as `en` or
                `es`. Omit it for the captions in the video's original language.
            use_ai_as_fallback: Ignored. Only captions already available from TikTok
                are returned.
            timeout: Overrides the client's timeout for this request.

        Returns:
            A :class:`~tapline.tiktok.TikTokTranscriptResponse`.
        """
        return self._send(
            _get_transcript(url=url, language=language, use_ai_as_fallback=use_ai_as_fallback),
            timeout=timeout,
        )
